mapper.select:
/*selectMasterMpIfWarehousingList*/
SELECT /*+USE_NL(A B) INDEX(A IF_GRDT_03) INDEX(B ICOMPODT_T04) INDEX(C ICOMPRDT_09) INDEX(AA SYS_C009853) */ (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BUYER ) AS BUYER_NAME /* 고객사명 */ , A.BUYER /* 고객사코드 */ , CASE WHEN AA.IF_FLAG = 'C' THEN '1' /* 작업대기 */ WHEN AA.IF_FLAG <> 'C' AND A.IF_FLAG = 'N' THEN '0' /* 정상 */ WHEN AA.IF_FLAG IS NULL AND A.IF_FLAG = 'N' THEN '0' /* 정상 */ WHEN AA.IF_FLAG <> 'C' AND A.IF_FLAG = 'E' THEN '2' /* 오류건 */ WHEN AA.IF_FLAG IS NULL AND A.IF_FLAG = 'E' THEN '2' /* 오류건 */ END IF_PROGRESS_GR /* 인터페이스상태 Image */ , AA.IF_FLAG AS IF_FLAG_PROGRESS /* 인터페이스상태 Flag */ , A.LEGACY_GR_NO AS LEGACY_GR_NO /* 입고번호 */ , A.LEGACY_GR_SEQ AS LEGACY_GR_SEQ /* 입고항번 */ , DECODE(A.STATUS, 'C', '3', 'R','4', 'D', '5') AS IF_STATUS /* 입고상태 */ , DECODE(B.STATUS, 'C', '3', 'R','4', 'D', '5', '', '6') AS PO_STATUS /* 발주상태 */ , A.STATUS AS IF_EXCEL /* 입고상태 */ , B.STATUS AS PO_EXCEL /* 발주상태 */ , A.ERROR_MSG AS ERROR_MSG /* 오류내역 */ , A.BUYER_ITEM_NO AS BUYER_ITEM_NO /* 품목코드 */ , C.DESCRIPTION AS DESCRIPTION /* 품명 */ , C.SPECIFICATION AS SPECIFICATION /* 규격 */ , B.ITEM_QTY AS ITEM_QTY /* 발주수량 */ , B.GR_QTY AS GR_QTY /* 기입고수량 */ , A.GR_QTY AS GR_QTY_IF /* IF입고수량 */ , A.RO_QTY AS RO_QTY /* IF반품수량 */ , A.UNIT_PRICE AS UNIT_PRICE_IF /* IF입고단가 */ , B.UNIT_PRICE AS UNIT_PRICE_PO /* 발주단가 */ , A.GR_DATE AS GR_DATE /* 입고일 */ , C.ADD_DATE AS ADD_DATE /* 발주일 */ , A.LEGACY_PO_NO AS LEGACY_PO_NO /* 주문번호 */ , A.LEGACY_PO_SEQ AS LEGACY_PO_SEQ /* 주문행번 */ , B.PR_NO AS PR_NO /* PR번호 */ , B.PR_SEQ AS PR_SEQ /* PR항번 */ , B.PO_NO AS PO_NO /* 발주번호 */ , B.PO_SEQ AS PO_SEQ /* 발주행번 */ , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE='M034' AND CODE=B.PROCESS_TYPE) AS PROCESS_TYPE_NM /* 거래유형 */ , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = F.AGENT ) AS AGENT_NAME /* 협력사명 */ , A.CREATE_DATE AS CREATE_DATE /* 생성일자 */ , A.CREATE_TIME AS CREATE_TIME /* 생성시간 */ , A.LOAD_DATE AS LOAD_DATE /* 작업일자 */ , A.LOAD_TIME AS LOAD_TIME /* 작업시간 */ FROM IF_GRDT A /* 인터페이스 입고내역 */ LEFT OUTER JOIN ICOMPODT B ON (1 = 1 /* 발주 제품정보 */ AND B.BUYER = A.BUYER AND B.LEGACY_PO_NO = A.LEGACY_PO_NO AND B.LEGACY_PO_SEQ = A.LEGACY_PO_SEQ AND B.BUYER_ITEM_NO = A.BUYER_ITEM_NO AND B.PO_NO = A.PO_NO AND B.PO_SEQ = A.PO_SEQ ) LEFT OUTER JOIN ICOMPRDT C ON (1 = 1 /* 구매요청 제품정보 */ AND C.BUYER = B.BUYER AND C.PR_NO = B.PR_NO AND C.PR_SEQ = B.PR_SEQ ) INNER JOIN IF_PROGRESS AA ON (1 = 1 /* 오류 현황 메인 */ AND AA.BUYER = A.BUYER AND AA.GUBUN = 'GR' AND AA.LEGACY_NO = A.LEGACY_GR_NO ) LEFT OUTER JOIN ICOMPOHD F ON (1 = 1 /* 발주 마스터정보 */ AND F.BUYER = B.BUYER AND F.PO_NO = B.PO_NO ) WHERE 1=1 AND A.IF_FLAG <> 'D'
AND A.BUYER IN ( SELECT /*+INDEX(MIS_BUYER_MNG MIS_BUYER_MNG_IDX)*/ DISTINCT BUYER FROM MIS_BUYER_MNG /* 고객사별 담당자 정보 */ WHERE 1 = 1 AND YEAR = TO_CHAR(SYSDATE,'YYYY') AND STATUS = 'C' -- AND PRIORITY = 'Y'
AND BUYER IN
#{item}
AND KEP_DEPT = #{st_user_dept}
AND KEP_USER_ID = #{st_user_id}
)
AND A.LEGACY_GR_NO LIKE '%' || #{st_legacy_gr_no} || '%'
AND A.LEGACY_PO_NO LIKE '%' || #{st_legacy_po_no} || '%'
AND A.BUYER_ITEM_NO LIKE '%' || #{st_buyer_item_no} || '%'
AND A.BUYER IN
#{item}
AND A.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.IF_FLAG = 'E'
AND A.IF_FLAG IN ('E','N')
